SELECT CASE WHEN suppliers.rating >= 3.7 THEN 'high' WHEN suppliers.rating >= 1.4 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(inventory.quantity) AS quantity_count FROM inventory INNER JOIN products ON products.id = inventory.product_id LEFT JOIN suppliers ON products.supplier_id = suppliers.id WHERE inventory.store_id IN (3, 4, 6) GROUP BY CASE WHEN suppliers.rating >= 3.7 THEN 'high' WHEN suppliers.rating >= 1.4 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket ASC;
